// Regenerates src/screens.data.ts from docs/11-screen-inventory.md so the
// in-app screen index can never drift from the checked inventory. Run with
// --check in CI to fail when the generated file is stale.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const inventory = fs.readFileSync(path.join(root, 'docs/11-screen-inventory.md'), 'utf8');
const rows = [...inventory.matchAll(/^\|\s*([A-Z]{2,4}-\d{2})\s*\|\s*(.+?)\s*\|\s*(.+?)\s*\|\s*[\d,\s]+\|\s*$/gm)];
if (rows.length !== 462) throw new Error(`Parsed ${rows.length} inventory rows; expected all 462 unique screen IDs.`);
let out = '// Generated by scripts/gen-screens.mjs from docs/11-screen-inventory.md — do not edit by hand.\n';
out += "// Regenerate with `npm run screens`, then verify with `npm run screens -- --check`.\n";
out += "import type { ScreenMeta } from './screens';\n\n";
out += 'export const SCREENS: Record<string, ScreenMeta> = {\n';
for (const [, id, title, purpose] of rows) {
  out += `${JSON.stringify(id)}:{title:${JSON.stringify(title)},purpose:${JSON.stringify(purpose)}},\n`;
}
out += '};\n';
const target = path.join(root, 'src/screens.data.ts');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== out) throw new Error('Screen data differs from the inventory; run npm run screens.');
  console.log(`PASS: ${rows.length} screens match docs/11-screen-inventory.md.`);
} else {
  fs.writeFileSync(target, out);
  console.log(`Generated ${rows.length} screen entries into src/screens.data.ts.`);
}
